package banghak.home.halley.adapter.outbound.persistence;
import banghak.home.halley.domain.budget.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toInstant; import org.jooq.DSLContext; import org.jooq.Record; import org.springframework.stereotype.Repository; import java.util.List; import java.util.Optional; import static banghak.home.halley.adapter.outbound.persistence.jdbc.HouseholdBudgetPlanTable.*; import static banghak.home.halley.adapter.outbound.persistence.support.JooqMapping.toEnum;
@Repository public class HouseholdBudgetPlanRepository { private final DSLContext dsl; public HouseholdBudgetPlanRepository(DSLContext dsl){this.dsl=dsl;} public BudgetPlan save(BudgetPlan p){Long id=dsl.insertInto(TABLE).set(GROUP_ID,p.groupId()).set(CREATED_BY,p.createdBy()).set(PLAN_NAME,p.planName()).set(SCENARIO,p.scenario().name()).set(SELECTED_PROPERTY_ID,p.selectedPropertyId()).set(HOUSING_TYPE,p.housingType().name()).set(REGION,p.region()).set(HOUSE_NAME,p.houseName()).set(PURCHASE_PRICE,p.purchasePrice()).set(EXCLUSIVE_AREA,p.exclusiveAreaM2()).set(CONTRACT_CASH,p.contractCash()).set(BALANCE_CASH,p.balanceCash()).set(ACQUISITION_TAX,p.acquisitionTax()).set(BROKERAGE_FEE,p.brokerageFee()).set(REGISTRATION_FEE,p.registrationFee()).set(MOVING_COST,p.movingCost()).set(CLEANING_COST,p.cleaningCost()).set(OTHER_INITIAL_COST,p.otherInitialCost()).set(PARENT_SUPPORT,p.parentSupport()).set(OTHER_FUNDS,p.otherFunds()).set(MONTHLY_MANAGEMENT_FEE,p.monthlyManagementFee()).set(MONTHLY_OTHER_HOUSING_COST,p.monthlyOtherHousingCost()).returningResult(ID).fetchOne().component1(); return findById(id).orElseThrow();} public Optional<BudgetPlan> findById(Long id){return dsl.selectFrom(TABLE).where(ID.eq(id)).fetchOptional().map(this::map);} public List<BudgetPlan> findByGroupId(Long groupId){return dsl.selectFrom(TABLE).where(GROUP_ID.eq(groupId)).orderBy(UPDATED_AT.desc()).fetch().map(this::map);} public void delete(Long id){dsl.deleteFrom(TABLE).where(ID.eq(id)).execute();} private BudgetPlan map(Record r){return new BudgetPlan(r.get(ID),r.get(GROUP_ID),r.get(CREATED_BY),r.get(PLAN_NAME),toEnum(BudgetScenario.class,r.get(SCENARIO)),r.get(SELECTED_PROPERTY_ID),toEnum(HousingType.class,r.get(HOUSING_TYPE)),r.get(REGION),r.get(HOUSE_NAME),r.get(PURCHASE_PRICE),r.get(EXCLUSIVE_AREA),r.get(CONTRACT_CASH),r.get(BALANCE_CASH),r.get(ACQUISITION_TAX),r.get(BROKERAGE_FEE),r.get(REGISTRATION_FEE),r.get(MOVING_COST),r.get(CLEANING_COST),r.get(OTHER_INITIAL_COST),r.get(PARENT_SUPPORT),r.get(OTHER_FUNDS),r.get(MONTHLY_MANAGEMENT_FEE),r.get(MONTHLY_OTHER_HOUSING_COST),toInstant(r.get(CREATED_AT)),toInstant(r.get(UPDATED_AT)));} }
